"""PRD content module for the Brevo MCP server."""

TOOLS = [
    ("brevo_preflight", "Read", "Pass/fail checklist: API key valid, credits remaining, enforced sender exists and is active, dry-run state."),
    ("brevo_get_account", "Read", "Account company, plan and remaining email credits."),
    ("brevo_list_senders", "Read", "Verified sender identities with active flag."),
    ("brevo_check_domain_auth", "Read", "DKIM, DMARC and Brevo-code status for one sending domain."),
    ("brevo_list_lists", "Read", "Contact lists with subscriber and blacklist counts."),
    ("brevo_list_folders", "Read", "Contact folders; a folderId is required to create a list."),
    ("brevo_get_contact", "Read", "One contact by email, including blacklist status and list membership."),
    ("brevo_list_contacts_in_list", "Read", "Contacts belonging to a given list id."),
    ("brevo_get_import_status", "Read", "Status of an async contact import by processId."),
    ("brevo_list_campaigns", "Read", "Campaigns filtered by status, with headline statistics."),
    ("brevo_get_campaign", "Read", "One campaign with full delivery and engagement statistics."),
    ("brevo_get_email_events", "Read", "Per-recipient events: bounces, spam, opens, clicks, unsubscribes."),
    ("brevo_campaign_report", "Read", "Cross-campaign deliverability report with MPP-corrected open rate and threshold warnings."),
    ("brevo_create_list", "Write", "Create a contact list in a folder; returns the new list id."),
    ("brevo_import_contacts", "Write", "Bulk import contacts into a list from inline CSV; returns a processId."),
    ("brevo_blacklist_contact", "Write", "Permanent opt-out; no future campaign can email the address."),
    ("brevo_create_campaign", "Write", "Create a campaign. Always a DRAFT; sender-lock enforced; no send option exists."),
    ("brevo_update_campaign", "Write", "Patch a draft campaign; only supplied fields change."),
    ("brevo_send_test_email", "Write", "Send a test copy to 1-10 named addresses only."),
    ("brevo_schedule_campaign", "Write", "Schedule a future send. Requires confirm=\"SCHEDULE\" and passes the sender lock."),
    ("brevo_send_campaign_now", "Write", "IRREVERSIBLE full-list send. Requires confirm=\"SEND\" and passes the sender lock."),
]

READ_COUNT = sum(1 for t in TOOLS if t[1] == "Read")
WRITE_COUNT = sum(1 for t in TOOLS if t[1] == "Write")

